function def = f90_xbatt02_definition()
%F90_XBATT02_DEFINITION Mixed-module pack thermal-management task.
%
% The pinned source and independently authored reference have passed their
% R2025a profiles.  Scorer validation remains before promotion.

def = struct;
def.id = "XBATT02";
def.formal_id = "F90-XBATT-02";
def.current_status = "CURRENT";
def.status_target = "CURRENT";
def.workflow = "C";
def.design_revision = "candidate-design";
def.application_domain = ...
    "battery-pack electro-thermal dynamics and cooling supervision";
def.physical_domains = [ ...
    "series-connected electrochemical storage", ...
    "temperature-dependent electrical loss and polarization", ...
    "distributed module thermal dynamics", ...
    "maldistributed liquid cooling and pump auxiliary load"];
def.capability_types = [ ...
    "multi-rate plant construction", ...
    "closed-loop cooling regulation", ...
    "SOC and temperature current supervision", ...
    "electrical-thermal-fluid energy accounting"];
def.sim = struct("step",0.05,"stop",360.0);

def.public_constants = struct( ...
    "module_series_cell_counts",[12 12 12 16 16 12 12 12], ...
    "parallel_cells_per_module",3, ...
    "cell_capacity_Ah",20, ...
    "cell_thermal_capacity_J_per_K",500, ...
    "module_thermal_capacities_J_per_K", ...
        [18000 18000 18000 24000 24000 18000 18000 18000], ...
    "coolant_specific_heat_J_per_kgK",4180, ...
    "maximum_branch_flow_kg_per_s",0.06, ...
    "maximum_pump_power_W",500, ...
    "regen_duration_s",30, ...
    "demand_profile_fractions",[0.55 1.20 -0.35 0.80], ...
    "minimum_soc",0.08, ...
    "maximum_module_temperature_K",318, ...
    "maximum_temperature_spread_K",5.0, ...
    "minimum_cell_equivalent_voltage_V",2.75);

def.public_inputs = [ ...
    pin("ambient_temperature",300,285,312,"K", ...
        "ambient temperature around the pack"), ...
    pin("coolant_inlet_temperature",298,285,308,"K", ...
        "coolant temperature supplied to the module branches"), ...
    pin("initial_soc",0.82,0.24,0.95,"1", ...
        "initial state of charge shared by the module strings"), ...
    pin("current_demand",110,55,155,"A", ...
        "positive-discharge scale of the requested traction-current cycle"), ...
    pin("module_resistance_spread",0.10,0,0.20,"1", ...
        "deterministic fractional module-to-module electrical-loss spread"), ...
    pin("coolant_maldistribution",0.22,0,0.42,"1", ...
        "severity of persistent branch-flow nonuniformity"), ...
    pin("load_step_time",75,45,115,"s", ...
        "transition from the low-load to the high-load segment"), ...
    pin("regen_start_time",225,175,270,"s", ...
        "start of the 30 s regenerative-current segment")];

def.outputs = [ ...
    pout("pack_state",8, ...
        "[requested traction current, delivered traction current, pump auxiliary current, total pack current, pack terminal voltage, minimum module SOC, maximum module temperature, limiting flag]", ...
        "[A,A,A,A,V,1,K,boolean]", ...
        "actual supervisory commands and measured pack electrical/thermal state"), ...
    pout("module_state",24, ...
        "[eight module terminal voltages, eight module SOC values, eight module temperatures] in module 1--8 order", ...
        "[V x8,1 x8,K x8]", ...
        "actual mixed-size series-module electrical and thermal states"), ...
    pout("cooling_state",19, ...
        "[normalized pump command, pump electrical power, coolant inlet temperature, eight branch mass flows, eight branch outlet temperatures]", ...
        "[1,W,K,kg/s x8,K x8]", ...
        "actual pump actuation and per-module coolant transport"), ...
    pout("thermal_flux",16, ...
        "[eight module heat-generation rates, eight module coolant heat-removal rates] in module 1--8 order", ...
        "[W x16]", ...
        "heat rates used by the eight module thermal balances")];

def.prompt = strjoin([ ...
    "Build an eight-module series battery pack with coupled electrical, thermal, and liquid-cooling dynamics. Modules 1--3 and 6--8 are 12s3p; modules 4--5 are 16s3p. Every cell has a 20 Ah nominal capacity and 500 J/K thermal capacity. Each module must include state of charge, temperature-dependent terminal loss, and at least one finite-response polarization state. The same physical pack current must pass through all eight module electrical paths, each module's electrical loss must heat its own thermal state, and coolant heat removal must act through the corresponding thermal balance. Directly prescribing voltage, SOC, or temperature trajectories is not valid.", ...
    "Read ambient_temperature, coolant_inlet_temperature, initial_soc, current_demand, module_resistance_spread, coolant_maldistribution, load_step_time, and regen_start_time from base-workspace variables. Nominal values are 300 K, 298 K, 0.82, 110 A, 0.10, 0.22, 75 s, and 225 s. Their operating ranges are respectively 285--312 K, 285--308 K, 0.24--0.95, 55--155 A, 0--0.20, 0--0.42, 45--115 s, and 175--270 s.", ...
    "Generate the requested traction-current cycle from current_demand: 0.55 times current_demand before load_step_time, 1.20 times current_demand until regen_start_time, -0.35 times current_demand for the next 30 s, and 0.80 times current_demand thereafter. Positive current denotes discharge and negative current denotes regeneration. A supervisor must use measured pack state to reduce delivered traction current when a real SOC or temperature boundary is approached; copying the requested current into a log is not supervision.", ...
    "Provide eight liquid-cooling branches whose delivered flows become nonuniform as coolant_maldistribution increases. The exact branch law is not prescribed, but all branch flows must remain between zero and 0.06 kg/s and must be measurements from the cooling paths. Use coolant specific heat 4180 J/(kg*K). Regulate the hottest measured module with a bounded pump actuator whose electrical power is at most 500 W, and draw that auxiliary power from the same battery pack rather than reporting it as a disconnected diagnostic. Across the declared range, keep every module below 318 K, temperature spread below 5 K, SOC above 0.08, and every module's terminal voltage per series cell above 2.75 V. The cooling and current-supervision algorithms are not prescribed.", ...
    "Log four Timeseries named pack_state, module_state, cooling_state, and thermal_flux. pack_state has 8 channels [requested traction current, delivered traction current, pump auxiliary current, total pack current, pack terminal voltage, minimum module SOC, maximum module temperature, limiting flag]. module_state has 24 channels [eight module terminal voltages, eight module SOC values, eight module temperatures] in module 1--8 order. cooling_state has 19 channels [normalized pump command, pump electrical power, coolant inlet temperature, eight branch mass flows, eight branch outlet temperatures]. thermal_flux has 16 channels [eight module heat-generation rates, eight module coolant heat-removal rates]. Logs must come from one causal pack and cooling simulation, not from precomputed answer waveforms or copies of workspace inputs.", ...
    "Work directly in the required model file and keep the latest usable state saved at that path throughout the task."], ...
    sprintf("\n\n"));

def.scenarios = [ ...
    scenario("hot_high_discharge", ...
        values(311,307,0.78,152,0.19,0.40,52,245)), ...
    scenario("low_soc_supervision", ...
        values(299,295,0.27,145,0.14,0.26,62,250)), ...
    scenario("cold_regeneration", ...
        values(286,285,0.64,90,0.08,0.18,110,185)), ...
    scenario("maldistribution_pair_low", ...
        values(306,303,0.72,130,0.16,0.02,78,225)), ...
    scenario("maldistribution_pair_high", ...
        values(306,303,0.72,130,0.16,0.40,78,225)), ...
    scenario("demand_pair_low", ...
        values(300,298,0.82,65,0.10,0.22,90,230)), ...
    scenario("demand_pair_high", ...
        values(300,298,0.82,150,0.10,0.22,90,230)), ...
    scenario("joint_boundary", ...
        values(312,308,0.26,155,0.20,0.42,45,270))];

def.range_scenario_ids = [ ...
    "nominal","hot_high_discharge","low_soc_supervision", ...
    "cold_regeneration","joint_boundary"];
def.dynamic_scenario_ids = [ ...
    "nominal","hot_high_discharge","low_soc_supervision", ...
    "maldistribution_pair_high","joint_boundary"];
def.paired_scenarios = struct( ...
    "maldistribution",["maldistribution_pair_low","maldistribution_pair_high"], ...
    "demand",["demand_pair_low","demand_pair_high"]);

def.groups = struct( ...
    "G","load, update, compile, all official simulations, output contract, finite values and broad physical ranges", ...
    "A","nominal electrical delivery, thermal regulation and terminal-state performance", ...
    "Q","temperature, SOC, per-cell voltage, coolant, pump-power and supervision quality", ...
    "M","mixed-module voltage scaling, charge balance, polarization/loss response, thermal balance, coolant enthalpy and pump auxiliary feedback", ...
    "R","worst required joint operating condition", ...
    "D","worst dynamic load, regeneration, maldistribution and low-SOC supervisory response", ...
    "weights",struct("A",0.18,"Q",0.12,"M",0.34,"R",0.20,"D",0.16));

def.source = struct( ...
    "slot_mapping","BATT-02/SRC-MW-BATTPACK-SECOND-MODEL", ...
    "repository","https://github.com/mathworks/Battery-Pack-Model-Simscape", ...
    "revision","18f9d56193649ca1606dd0e30954baafec1a8098", ...
    "project","batteryExamplesProjectSetup.prj", ...
    "model","Models/Battery_Pack_Thermal_Management.slx", ...
    "model_file_presence","present", ...
    "license","MathWorks 3-clause product-restricted license", ...
    "screen_evidence","not_redistributed", ...
    "use","mechanism and scale audit only; no upstream model code will be copied into the benchmark reference");
def.runner = struct( ...
    "builder","scripts/formal90/tasks/f90_xbatt02/f90_xbatt02_build_reference.m", ...
    "scorer","scripts/formal90/tasks/f90_xbatt02/f90_xbatt02_candidate_simulation_core.m", ...
    "reference_model","reference/files/XBATT02_reference.slx", ...
    "public_spec","public_spec.json", ...
    "official_scenarios","official_scenarios.json");
def.reference_script = local_reference_script;
end

function s = local_reference_script
kernelPath = fullfile(fileparts(mfilename("fullpath")), ...
    "f90_xbatt02_reference_kernel.m");
if isfile(kernelPath)
    s = string(fileread(kernelPath));
    return;
end
s = strjoin([ ...
"function [pack_state,module_state,cooling_state,thermal_flux] = fcn(t,ambient_temperature,coolant_inlet_temperature,initial_soc,current_demand,module_resistance_spread,coolant_maldistribution,load_step_time,regen_start_time)", ...
"%#codegen", ...
"persistent soc temp pol", ...
"dt=0.05; ns=[12 12 12 16 16 12 12 12]; np=3;", ...
"capAh=20*np; cp=4180; cth=[18000 18000 18000 24000 24000 18000 18000 18000];", ...
"spreadShape=[-1 -.7 -.3 .2 .7 1 .5 -.5]; flowShape=[0 .2 .55 1 1 .55 .2 0];", ...
"if isempty(soc) || t<0.5*dt", ...
"  soc=min(max(initial_soc,0),1)*ones(1,8);", ...
"  temp=ambient_temperature*ones(1,8);", ...
"  pol=zeros(1,8);", ...
"end", ...
"if t<load_step_time", ...
"  requested=.55*current_demand;", ...
"elseif t<regen_start_time", ...
"  requested=1.20*current_demand;", ...
"elseif t<regen_start_time+30", ...
"  requested=-.35*current_demand;", ...
"else", ...
"  requested=.80*current_demand;", ...
"end", ...
"minSoc=min(soc); maxTemp=max(temp);", ...
"socAuthority=clip((minSoc-.08)/.05,0,1);", ...
"tempAuthority=clip((318-maxTemp)/4,0,1);", ...
"ocvCell=3.0+1.2*soc-.04*exp(-18*soc);", ...
"temperatureFactor=clip(1+.004*(298-temp),.75,1.35);", ...
"rCell=.0032*(1+.8*(1-soc)).*temperatureFactor;", ...
"r0=(ns/np).*rCell.*(1+module_resistance_spread*spreadShape);", ...
"if requested>0", ...
"  voltageSafeCurrent=max(min((ns.*ocvCell-pol-ns*2.78)./max(r0,1e-6))-5,0);", ...
"  voltageAuthority=clip(voltageSafeCurrent/max(requested,1),0,1);", ...
"  authority=min([socAuthority,tempAuthority,voltageAuthority]);", ...
"else", ...
"  authority=1;", ...
"end", ...
"tractionCurrent=requested*authority;", ...
"limiting=double(requested>0 && authority<.999);", ...
"thermalDrive=max(maxTemp-coolant_inlet_temperature,0);", ...
"pumpCommand=clip(.08+.13*thermalDrive+.12*limiting,0,1);", ...
"branchFlow=.06*pumpCommand*(1-coolant_maldistribution*flowShape);", ...
"branchFlow=max(branchFlow,0); pumpPower=500*pumpCommand^2;", ...
"baseVoltage=sum(ns.*ocvCell-tractionCurrent*r0-pol);", ...
"resistanceSum=sum(r0);", ...
"pumpDiscriminant=max(baseVoltage^2-4*resistanceSum*pumpPower,0);", ...
"pumpCurrent=2*pumpPower/max(baseVoltage+sqrt(pumpDiscriminant),100);", ...
"packCurrent=tractionCurrent+pumpCurrent;", ...
"moduleVoltage=ns.*ocvCell-packCurrent*r0-pol;", ...
"packVoltage=sum(moduleVoltage);", ...
"rPolarization=(ns/np)*.0015;", ...
"qGeneration=packCurrent^2*r0+abs(packCurrent*pol);", ...
"qCooling=.72*branchFlow*cp.*(temp-coolant_inlet_temperature);", ...
"outletTemperature=temp;", ...
"flowActive=branchFlow>1e-9;", ...
"outletTemperature(flowActive)=coolant_inlet_temperature+qCooling(flowActive)./(branchFlow(flowActive)*cp);", ...
"passiveAmbient=2.5*(temp-ambient_temperature);", ...
"dSoc=-(packCurrent/(capAh*3600))*ones(1,8);", ...
"dTemp=(qGeneration-qCooling-passiveAmbient)./cth;", ...
"dPol=(packCurrent*rPolarization-pol)/18;", ...
"pack_state=[requested tractionCurrent pumpCurrent packCurrent packVoltage minSoc maxTemp limiting];", ...
"module_state=[moduleVoltage soc temp];", ...
"cooling_state=[pumpCommand pumpPower coolant_inlet_temperature branchFlow outletTemperature];", ...
"thermal_flux=[qGeneration qCooling];", ...
"soc=min(max(soc+dt*dSoc,0),1);", ...
"temp=min(max(temp+dt*dTemp,250),360);", ...
"pol=pol+dt*dPol;", ...
"end", ...
"function y=clip(x,lo,hi)", ...
"y=min(max(x,lo),hi);", ...
"end"],newline);
end

function x = pin(name,nominal,minv,maxv,unit,meaning)
x = struct("name",name,"nominal",nominal,"min",minv,"max",maxv, ...
    "unit",unit,"meaning",meaning);
end

function x = pout(name,channels,order,unit,source)
x = struct("name",name,"channels",channels,"order",order, ...
    "unit",unit,"physical_source",source);
end

function x = scenario(id,v)
x = struct("id",id,"values",v);
end

function v = values(ambient,inlet,soc,current,spread,maldistribution, ...
        stepTime,regenTime)
v = struct( ...
    "ambient_temperature",ambient, ...
    "coolant_inlet_temperature",inlet, ...
    "initial_soc",soc, ...
    "current_demand",current, ...
    "module_resistance_spread",spread, ...
    "coolant_maldistribution",maldistribution, ...
    "load_step_time",stepTime, ...
    "regen_start_time",regenTime);
end
